function Migrate-LegacyExternalBinary([string]$Source, [string]$Destination) {
    if (-not $Source) { return }
    if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) { return }
    if ($Source -eq $Destination) { return }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) { return }
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Destination -Force
    Write-Host "✓ Recovered managed binary: $Source → $Destination"
}

# Pre-detection recovery for old installs that incorrectly placed RTK/Codex
# inside the replaceable LazyDev runtime directory.
foreach ($candidate in @($PersistedRtkCommand, (Join-Path $InstallRoot 'rtk'), (Join-Path $InstallRoot 'bin\rtk.exe'), (Join-Path "$InstallRoot.previous" 'rtk.exe'), (Join-Path "$InstallRoot.previous" 'bin\rtk.exe'))) {
    if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
        $destination = Join-Path $ExternalBinRoot 'rtk.exe'
        Migrate-LegacyExternalBinary $candidate $destination
        if (Test-Path -LiteralPath $destination -PathType Leaf) { $PersistedRtkCommand = $destination; break }
    }
}
foreach ($candidate in @($PersistedCodexCommand, (Join-Path $InstallRoot 'codex.exe'), (Join-Path $InstallRoot 'codex.bin'), (Join-Path $InstallRoot 'bin\codex.exe'), (Join-Path "$InstallRoot.previous" 'codex.exe'), (Join-Path "$InstallRoot.previous" 'codex.bin'), (Join-Path "$InstallRoot.previous" 'bin\codex.exe'))) {
    if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
        $destination = Join-Path $ExternalBinRoot 'codex.exe'
        Migrate-LegacyExternalBinary $candidate $destination
        if (Test-Path -LiteralPath $destination -PathType Leaf) { $PersistedCodexCommand = $destination; break }
    }
}

function Step([string]$Message) { Write-Host "`n==> $Message" }
function Fail([string]$Message) { throw $Message }
function Write-InstallState {
    try {
        New-Item -ItemType Directory -Path $StateRoot -Force | Out-Null
        $payload = [ordered]@{
            version = 6
            bin_dir = $BinRoot
            lazydev_command = Join-Path $BinRoot 'lazydev.cmd'
            kimi_bin_dir = $KimiBinRoot
            rtk_bin_dir = $RtkBinRoot
            codex_bin_dir = $CodexBinRoot
            kimi_command = $PersistedKimiCommand
            codex_command = $PersistedCodexCommand
            antigravity_command = $PersistedAntigravityCommand
            claude_command = $PersistedClaudeCommand
            rtk_command = $PersistedRtkCommand
            ui_runtime_dir = $LazyDevUiHome
        } | ConvertTo-Json
        $tmp = "$StateFile.$PID.tmp"
        Set-Content -LiteralPath $tmp -Value $payload -Encoding UTF8
        if (Test-Path -LiteralPath $StateFile -PathType Leaf) {
            Copy-Item -LiteralPath $StateFile -Destination $StateBackupFile -Force -ErrorAction SilentlyContinue
        }
        Move-Item -LiteralPath $tmp -Destination $StateFile -Force
        try {
            $registry = [ordered]@{ version = 1; rtk_command = $PersistedRtkCommand; codex_command = $PersistedCodexCommand; kimi_command = $PersistedKimiCommand; antigravity_command = $PersistedAntigravityCommand; claude_command = $PersistedClaudeCommand }
            $rtmp = "$CliRegistryFile.$PID.tmp"
            if (Test-Path -LiteralPath $CliRegistryFile -PathType Leaf) { Copy-Item -LiteralPath $CliRegistryFile -Destination $CliRegistryBackupFile -Force -ErrorAction SilentlyContinue }
            $registry | ConvertTo-Json | Set-Content -LiteralPath $rtmp -Encoding UTF8
            Move-Item -LiteralPath $rtmp -Destination $CliRegistryFile -Force
        } catch {}
    } catch {}
}
function Get-VersionFromText([string]$Text) {
    $m = [regex]::Match($Text, '(\d+\.\d+\.\d+)')
    if ($m.Success) { return $m.Groups[1].Value }
    return ''
}
function Test-VersionAtLeast([string]$Current, [string]$Required) {
    try { return ([version]$Current -ge [version]$Required) } catch { return $false }
}
function Find-ExternalCliInHome([string[]]$Names) {
    $roots = @($HOME, (Join-Path $env:LOCALAPPDATA 'Programs'), (Join-Path $env:APPDATA 'npm')) | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) } | Select-Object -Unique
    foreach ($root in $roots) {
        try {
            $found = Get-ChildItem -LiteralPath $root -File -Recurse -Force -ErrorAction SilentlyContinue |
                Where-Object { $Names -contains $_.Name -and $_.FullName -notmatch '(?i)\\(node_modules|sessions|logs|\.cache|Cache|target|\.git)\\' } |
                Select-Object -First 1
            if ($found) { return $found.FullName }
        } catch {}
    }
    return $null
}

function Find-Kimi {
    foreach ($candidate in @(
        $PersistedKimiCommand,
        (Join-Path $KimiBinRoot 'kimi.exe'),
        (Join-Path $KimiBinRoot 'kimi.cmd'),
        (Join-Path $HOME '.kimi-code\bin\kimi.exe'),
        (Join-Path $BinRoot 'kimi.exe'),
        (Join-Path $BinRoot 'kimi.cmd'),
        (Join-Path $HOME '.local\share\lazydev\kimi.exe'),
        (Join-Path $HOME '.local\bin\kimi.exe'),
        (Join-Path $HOME '.local\bin\kimi.cmd'),
        (Join-Path $HOME '.volta\bin\kimi.cmd'),
        (Join-Path $HOME '.asdf\shims\kimi')
    )) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
    }
    foreach ($name in @('kimi.exe','kimi.cmd','kimi')) {
        $cmd = Get-Command $name -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd.Source }
    }
    return Find-ExternalCliInHome @('kimi.exe','kimi.cmd','kimi')
}
function Get-KimiVersion([string]$Exe) {
    if (-not $Exe) { return '' }
    try { return Get-VersionFromText ((& $Exe --version 2>$null) -join "`n") } catch { return '' }
}
function Find-Codex {
    foreach ($candidate in @(
        $PersistedCodexCommand,
        (Join-Path $CodexBinRoot 'codex.exe'), (Join-Path $CodexBinRoot 'codex.cmd'),
        (Join-Path $HOME '.codex\packages\standalone\current\codex'),
        (Join-Path $HOME '.local\share\lazydev\codex.exe'), (Join-Path $HOME '.local\share\lazydev\codex.cmd'),
        (Join-Path $HOME '.local\bin\codex.exe'), (Join-Path $HOME '.local\bin\codex.cmd')
    )) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
    }
    $cmd = Get-Command codex.exe,codex.cmd,codex -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cmd) { return $cmd.Source }
    $npmBins = @()
    try {
        $prefix = (& npm prefix -g 2>$null | Select-Object -Last 1)
        if ($prefix) { $npmBins += Join-Path ([string]$prefix) 'bin' }
    } catch {}
    foreach ($dir in $npmBins) {
        foreach ($name in @('codex.exe','codex.cmd')) {
            $candidate = Join-Path $dir $name
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
        }
    }
    return Find-ExternalCliInHome @('codex.exe','codex.cmd','codex')
}
function Find-Antigravity {
    foreach ($candidate in @(
        $PersistedAntigravityCommand,
        (Join-Path $env:LOCALAPPDATA 'agy\bin\agy.exe'),
        (Join-Path $env:LOCALAPPDATA 'agy\bin\agy.cmd'),
        (Join-Path $HOME '.volta\bin\agy.cmd'),
        (Join-Path $HOME '.local\bin\agy.exe'),
        (Join-Path $BinRoot 'agy.exe'),
        (Join-Path $BinRoot 'agy.cmd')
    )) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
    }
    $cmd = Get-Command agy.exe,agy.cmd,agy -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cmd) { return $cmd.Source }
    return Find-ExternalCliInHome @('agy.exe','agy.cmd','agy')
}
function Find-Claude {
    foreach ($candidate in @(
        $PersistedClaudeCommand,
        (Join-Path $HOME '.local\bin\claude.exe'),
        (Join-Path $HOME '.local\bin\claude.cmd'),
        (Join-Path $HOME '.local\bin\claude'),
        (Join-Path $HOME '.claude\bin\claude.exe'),
        (Join-Path $HOME '.claude\bin\claude.cmd'),
        (Join-Path $HOME '.claude\bin\claude')
    )) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
